sql.if:


WITH keyword_calc_items AS (
    SELECT ci.id FROM mrp_calc mc JOIN mrp_calc_item ci ON ci.calc_id = mc.id
    WHERE upper(mc.no) LIKE #{keywordCode}

        OR upper(mc.no) IN #{code}

    UNION
    SELECT ci.id FROM mrp_calc_item ci



            WHERE 
                ((upper(ci.order_nos) LIKE #{pattern.contains}
                  AND string_to_array(upper(ci.order_nos), ',') @> ARRAY[#{pattern.code}]::text[])
                 OR (upper(ci.style_codes) LIKE #{pattern.contains}
                     AND string_to_array(upper(ci.style_codes), ',') @> ARRAY[#{pattern.code}]::text[]))



            WHERE upper(ci.order_nos) LIKE #{keywordCode} OR upper(ci.style_codes) LIKE #{keywordCode}


), keyword_skus AS (
    SELECT k.id FROM bas_material_sku k WHERE upper(k.code) LIKE #{keywordCode}

        OR upper(k.code) IN #{code}

    UNION
    SELECT k.id FROM bas_material m JOIN bas_material_sku k ON k.material_id = m.id
    WHERE upper(m.code) LIKE #{keywordCode} OR m.name ILIKE #{keywordContains}

        OR upper(m.code) IN #{code}

), keyword_items AS (
    SELECT i.id, i.purchase_order_id FROM pur_order_item i JOIN keyword_skus k ON k.id = i.material_sku_id
    UNION
    SELECT i.id, i.purchase_order_id FROM pur_order_item i JOIN keyword_calc_items ci ON ci.id = i.calc_item_id
    UNION
    SELECT i.id, i.purchase_order_id FROM keyword_calc_items ci
    JOIN mrp_calc_transit t ON t.calc_item_id = ci.id JOIN pur_order_item i ON i.id = t.purchase_item_id
), keyword_heads AS (
    SELECT ko.id FROM pur_order ko WHERE upper(ko.no) LIKE #{keywordCode}

        OR upper(ko.no) IN #{code}

    UNION
    SELECT ko.id FROM sup_supplier ks JOIN pur_order ko ON ko.supplier_id = ks.id
    WHERE ks.name ILIKE #{keywordContains} OR ks.short_name ILIKE #{keywordContains}
)

mapper.sql:
WHERE true


        AND o.status = 'PENDING'


                AND EXISTS (
                    SELECT 1 FROM biz_approval_step approval
                    WHERE approval.biz_type = 'PURCHASE_ORDER' AND approval.doc_id = o.id AND approval.status = 'CURRENT'
                      AND (approval.user_id = #{q.approvalScope.userId}

                            OR approval.perm = #{q.approvalScope.permission}


                            OR approval.role_id IN #{roleId}
                        )
                )

            AND false



        AND (o.create_by = #{scope.userId} OR o.buyer_id = #{scope.userId})



    AND o.status IN #{s}

AND o.purchase_type = #{q.purchaseType}
AND o.supplier_id = #{q.supplierId}
AND o.buyer_id = #{q.buyerId}
AND o.order_date >= #{q.orderDateFrom}
AND o.order_date <= #{q.orderDateTo}

    AND o.id IN #{id}




    AND o.id IN (SELECT id FROM keyword_heads UNION SELECT purchase_order_id FROM keyword_items)

WHERE o.status IN ('APPROVED', 'RUNNING') AND i.received_qty - i.returned_qty < i.qty
AND (o.create_by = #{scope.userId} OR o.buyer_id = #{scope.userId})
AND o.supplier_id = #{q.supplierId}
AND o.buyer_id = #{q.buyerId}
AND COALESCE(i.line_due_date, o.delivery_date) >= #{q.dueDateFrom}
AND COALESCE(i.line_due_date, o.delivery_date) <= #{q.dueDateTo}



    AND i.id IN (SELECT id FROM keyword_items
                 UNION SELECT ki.id FROM pur_order_item ki JOIN keyword_heads kh ON kh.id = ki.purchase_order_id)
